package analysis

import "math"

// NormalizedPower is the fourth-power mean of the 30-second rolling average
// power (Coggan). 0 for activities shorter than 30 s or without power.
func NormalizedPower(t []int64, power []float64) float64 {
	grid := powerGrid(t, power)
	const window = 30
	if len(grid) < window {
		return 0
	}
	sum := 0.0
	for _, p := range grid[:window] {
		sum += p
	}
	var acc float64
	n := 0
	for i := window; ; i++ {
		avg := sum / window
		acc += avg * avg * avg * avg
		n++
		if i == len(grid) {
			break
		}
		sum += grid[i] - grid[i-window]
	}
	return math.Pow(acc/float64(n), 0.25)
}

// TSS is the training stress score of an effort: 100 for one hour at FTP.
func TSS(np float64, ftp int, seconds float64) float64 {
	if ftp <= 0 || np <= 0 || seconds <= 0 {
		return 0
	}
	intensity := np / float64(ftp)
	return seconds * np * intensity / (float64(ftp) * 3600) * 100
}

// maxTRIMPGap caps the time a single heart-rate sample counts for, so
// pauses without records do not add load.
const maxTRIMPGap = 10

// TRIMP is Banister's training impulse from heart rate: minutes weighted by
// the heart-rate reserve with an exponential factor (1.92 for men, 1.67 for
// women). 0 without heart rate or thresholds.
func TRIMP(t []int64, hr []float64, restHR, maxHR int, female bool) float64 {
	if maxHR <= restHR || restHR <= 0 {
		return 0
	}
	a, b := 0.64, 1.92
	if female {
		a, b = 0.86, 1.67
	}
	reserve := float64(maxHR - restHR)
	var sum float64
	for k := 0; k+1 < min(len(t), len(hr)); k++ {
		h := hr[k]
		if math.IsNaN(h) || h <= 0 {
			continue
		}
		dt := math.Min(float64(t[k+1]-t[k]), maxTRIMPGap)
		r := math.Max(0, math.Min(1, (h-float64(restHR))/reserve))
		sum += dt / 60 * r * a * math.Exp(b*r)
	}
	return sum
}

// HRZoneBounds returns Garmin's default heart-rate zones (50–100 % of the
// maximum heart rate) in the layout of fitfile.Zones: bounds[0] is the
// lower bound of zone 1.
func HRZoneBounds(maxHR int) []float64 {
	out := make([]float64, 0, 6)
	for _, pct := range []float64{50, 60, 70, 80, 90, 100} {
		out = append(out, math.Round(float64(maxHR)*pct/100))
	}
	return out
}

// PowerZoneBounds returns the seven Coggan power zones for an FTP.
func PowerZoneBounds(ftp int) []float64 {
	out := []float64{0}
	for _, pct := range []float64{55, 75, 90, 105, 120, 150} {
		out = append(out, math.Round(float64(ftp)*pct/100))
	}
	return append(out, 4000)
}

// TimeInZones returns the seconds per zone for values recorded at times t.
// Index 0 is below bounds[0]; values above the last bound count to the top
// zone. Each sample counts until the next one, at most maxTRIMPGap seconds.
func TimeInZones(t []int64, values []float64, bounds []float64) []float64 {
	if len(bounds) < 2 {
		return nil
	}
	out := make([]float64, len(bounds))
	any := false
	for k := 0; k+1 < min(len(t), len(values)); k++ {
		v := values[k]
		if math.IsNaN(v) {
			continue
		}
		dt := math.Min(float64(t[k+1]-t[k]), maxTRIMPGap)
		zone := len(bounds) - 1
		for i, b := range bounds {
			if v < b {
				zone = i
				break
			}
		}
		out[zone] += dt
		any = true
	}
	if !any {
		return nil
	}
	return out
}
